head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDBNS30301.xml";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vTrdDd = '';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.gform_onload = function() {
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
    }
    if (scwin.fn_GetPar != undefined) {
        var arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        scwin.vTrdDd = arrPar[0].TRD_DD;
        var url = "/bns/BnsCommon.do?method=readMktFile";
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&TRD_DD=" + scwin.vTrdDd;
        dts_MktFile.DataID = encodeURI(url);
        dts_MktFile.Reset();
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_MktFile_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_MktFile_OnLoadCompleted = function(rowcount) {
    if (rowcount > 0) {
        $c.stf.setObjectValue(txb_SendYn, 'Y');
        $c.stf.setObjectValue(txb_TrdDd, dts_MktFile.getCellData(1, 'TRD_DD') + ' ' + dts_MktFile.getCellData(1, 'TRNSM_TM'));
        $c.stf.setObjectValue(txa_Binfile, dts_MktFile.getCellData(1, 'BINFILE'));
    } else {
        $c.stf.setObjectValue(txb_SendYn, 'N');
        $c.stf.setObjectValue(txb_TrdDd, '-');
        $c.win.alert('시장지 데이터가 없습니다.');
    }
};
scwin.btn_DownloadFile_onclick = function() {
    if ($c.stf.getObjectValue(txb_SendYn) == '' ||
        $c.stf.getObjectValue(txb_SendYn) == 'N') return;
    var url = "/bns/BnsMktactFileDownload.do?";
    url += "TRD_DD=" + scwin.vTrdDd;
    location.href = url;
};
